import assert from "node:assert/strict";
import { randomBytes, randomUUID } from "node:crypto";
import { createServerClient, parseCookieHeader } from "@supabase/ssr";
import { devAuthAdmin, devProjectUrl, env, loopback, postgresClient } from "./dev-environment.mjs";

// Uses a real dev Auth/DB and one-use links generated by the admin API. No email is sent.
// This verifies confirmation/session/profile/group integration, not SMTP delivery.
async function smoke() {
  const origin = new URL(env("APP_URL"));
  assert(loopback.includes(origin.hostname), "Chỉ chạy smoke đăng ký với app local.");
  const projectUrl = devProjectUrl();
  const admin = devAuthAdmin();
  const db = postgresClient(env("DATABASE_URL"));
  const users = [];
  const marker = "OOPS_SIGNUP_TEST_" + randomUUID();
  await db.connect();

  function captureCookies(response, jar) {
    for (const header of response.headers.getSetCookie()) {
      for (const { name, value } of parseCookieHeader(header.split(";")[0])) {
        if (value) jar.set(name, value);
        else jar.delete(name);
      }
    }
  }

  async function request(path, jar = new Map(), body, method) {
    const headers = new Headers({ cookie: Array.from(jar, ([key, value]) => `${key}=${encodeURIComponent(value)}`).join("; ") });
    if (body !== undefined) {
      headers.set("origin", origin.origin);
      headers.set("content-type", "application/json");
      headers.set("idempotency-key", randomUUID());
    }
    const response = await fetch(new URL(path, origin), {
      method: method ?? (body === undefined ? "GET" : "POST"), headers,
      body: body === undefined ? undefined : JSON.stringify(body), redirect: "manual",
      signal: AbortSignal.timeout(60_000),
    });
    captureCookies(response, jar);
    return response;
  }

  async function newAccount(next = "/groups") {
    const location = { provinceCode: "79", wardCode: users.length ? "26740" : "26743" };
    const email = `oops-signup-${randomUUID()}@example.test`;
    const password = randomBytes(24).toString("base64url") + "aA1!";
    const phone = "0901234567";
    const { data, error } = await admin.generateLink({
      type: "signup", email, password, options: { data: { display_name: marker, phone, location } },
    });
    assert(!error, `Không tạo được link test: ${error?.code ?? "unknown"}`);
    assert(data.user?.id);
    users.push(data.user.id);
    const jar = new Map();
    const callback = `/login/confirm?${new URLSearchParams({ token_hash: data.properties.hashed_token, type: "email", next })}`;
    const response = await request(callback, jar);
    assert.equal(response.status, 303);
    assert.equal(response.headers.get("location"), next, "Callback chưa xác nhận tài khoản.");
    assert([...jar.keys()].some(key => key.includes("auth-token")), "Callback chưa ghi cookie phiên.");
    if (next === "/groups") {
      const home = await request(next, jar);
      assert.equal(home.status, 200);
      const homePage = await home.text();
      assert.match(homePage, /Tham gia nhóm qua lời mời/);
      assert.doesNotMatch(homePage, /Đầu mối nhận hỗ trợ/);
    }
    const [me, concurrentMe] = await Promise.all([
      request("/api/v1/me", jar),
      request("/api/v1/me", new Map(jar)),
    ]);
    assert.equal(me.status, 200, "Cookie xác nhận phải dùng được tại API hồ sơ.");
    assert.equal(concurrentMe.status, 200);
    const profileBody = await me.json();
    assert.equal(profileBody.userId, data.user.id);
    assert.deepEqual(profileBody.location, location);
    assert(profileBody.contactPrivate?.includes(`SĐT: ${phone}`), "Số điện thoại đăng ký phải được lưu vào hồ sơ.");
    assert(profileBody.groupId, "Tài khoản phải có nhóm riêng mặc định.");
    assert.equal((await concurrentMe.json()).groupId, profileBody.groupId);
    const { rows: [profile] } = await db.query("select display_name from public.profiles where id = $1", [data.user.id]);
    assert.equal(profile?.display_name, marker, "Tên đăng ký phải được lưu vào hồ sơ.");

    const reused = await request(callback);
    assert(reused.headers.get("location")?.includes("confirmation=failed"), "Link xác nhận chỉ dùng một lần.");

    // A fresh client must also be able to log in using the new account's password.
    const loginJar = new Map();
    const client = createServerClient(projectUrl, env("NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"), {
      cookies: {
        getAll: () => Array.from(loginJar, ([name, value]) => ({ name, value })),
        setAll: entries => entries.forEach(({ name, value }) => value ? loginJar.set(name, value) : loginJar.delete(name)),
      },
    });
    const login = await client.auth.signInWithPassword({ email, password });
    assert(!login.error && login.data.session, `Tài khoản vừa xác nhận phải đăng nhập được (${login.error?.code ?? "no_session"}, ${login.error?.status ?? 0}).`);
    assert.equal((await request("/api/v1/me", loginJar)).status, 200);
    await client.auth.signOut({ scope: "local" });
    return { userId: data.user.id, jar, location, groupId: profileBody.groupId };
  }

  try {
    assert.equal((await request("/api/v1/me")).status, 401);
    const owner = await newAccount();
    const { groupId } = owner;
    const invitation = await request(`/api/v1/groups/${groupId}/invites`, owner.jar, { kind: "JOIN" });
    assert.equal(invitation.status, 201);
    const { inviteUrl } = await invitation.json();
    const invite = new URL(inviteUrl);
    const member = await newAccount(invite.pathname + invite.search);
    assert.notEqual(member.groupId, groupId);
    const accepted = await request("/api/v1/invites/accept", member.jar, { token: invite.searchParams.get("token") });
    assert.equal(accepted.status, 200);
    assert.equal((await accepted.json()).groupId, groupId);
    assert.equal((await (await request("/api/v1/me", member.jar)).json()).groupId, groupId);
    assert.equal((await request(`/api/v1/groups/${member.groupId}`, member.jar)).status, 404);
    const group = await request(`/api/v1/groups/${groupId}`, member.jar);
    assert.equal(group.status, 200);
    const groupData = await group.json();
    assert.equal(groupData.members.length, 2);
    assert.deepEqual(groupData.location, owner.location);
    const campaignResponse = await request(`/api/v1/groups/${groupId}/campaigns`, owner.jar, {
      collectUntil: new Date(Date.now() + 3600000).toISOString(), needBy: new Date(Date.now() + 86400000).toISOString(),
    });
    assert.equal(campaignResponse.status, 201);
    const { campaignId } = await campaignResponse.json();
    const catalog = await (await request("/api/v1/catalog", owner.jar)).json();
    assert(catalog.items.length, "Dev catalog must contain at least one SKU.");
    const cartResponse = await request(`/api/v1/campaigns/${campaignId}/cart`, owner.jar, {
      version: 0, householdSize: 1, supportRequested: false,
      lines: [{ skuId: catalog.items[0].skuId, stockQty: 0, needQty: 2 }],
    }, "PUT");
    assert.equal(cartResponse.status, 200);
    const cart = await cartResponse.json();
    // New accounts have no Fuji wallet. Keep that guard intact; seed only our test cart
    // as confirmed to test publishing/location independently of the wallet workflow.
    const confirmation = await request(`/api/v1/campaigns/${campaignId}/cart/confirm`, owner.jar, { version: cart.version });
    assert.equal(confirmation.status, 409);
    assert.equal((await confirmation.json()).error.code, "WALLET_NOT_READY");
    await db.query("update public.carts set state = 'CONFIRMED' where id = $1 and campaign_id = $2", [cart.cartId, campaignId]);
    const published = await request(`/api/v1/campaigns/${campaignId}/publish`, owner.jar, {});
    assert.equal(published.status, 200);
    const { items: [demand] } = await published.json();
    assert.equal(demand.provinceCode, "79");
    assert.equal(demand.wardCode, owner.location.wardCode);
    const updated = await request("/api/v1/me", owner.jar, { location: member.location }, "PATCH");
    assert.equal(updated.status, 200);
    const groupAfterMove = await (await request(`/api/v1/groups/${groupId}`, owner.jar)).json();
    assert.deepEqual(groupAfterMove.location, member.location);
    // The representative moved, but the already published demand retains its snapshot.
    const correctFeed = await (await request(`/api/v1/feed?province=79&ward=${owner.location.wardCode}&limit=50`, member.jar)).json();
    assert(correctFeed.items.some(item => item.demandItemId === demand.demandItemId));
    const wrongFeed = await (await request(`/api/v1/feed?province=79&ward=${member.location.wardCode}&limit=50`, member.jar)).json();
    assert(!wrongFeed.items.some(item => item.demandItemId === demand.demandItemId));
    assert.equal((await request("/groups", member.jar)).status, 200);
    assert.equal((await request(`/api/v1/groups/${groupId}/leave`, member.jar, {})).status, 200);
    const afterLeave = await (await request("/api/v1/me", member.jar)).json();
    assert(afterLeave.groupId && afterLeave.groupId !== groupId);
    const soloGroup = await (await request(`/api/v1/groups/${afterLeave.groupId}`, member.jar)).json();
    assert.equal(soloGroup.repId, member.userId);
    assert.deepEqual(soloGroup.location, member.location);
    console.log("PASS: confirmation, automatic solo group, invite switch, leave, representative location and Feed snapshots.");
    console.log("NOT TESTED: public signup email delivery (admin.generateLink does not send email).");
    console.log("Fixture: only the temporary cart is marked confirmed in DB; the real wallet requirement remains enforced.");
  } finally {
    try {
      if (users.length) {
        await db.query("BEGIN");
        try {
          await db.query("delete from public.demand_shares where demand_item_id in (select d.id from public.demand_items d join public.campaigns c on c.id=d.campaign_id join public.groups g on g.id=c.group_id where g.name=$1)", [marker]);
          await db.query("delete from public.demand_items where campaign_id in (select c.id from public.campaigns c join public.groups g on g.id=c.group_id where g.name=$1)", [marker]);
          await db.query("delete from public.cart_items where cart_id in (select cart.id from public.carts cart join public.campaigns c on c.id=cart.campaign_id join public.groups g on g.id=c.group_id where g.name=$1)", [marker]);
          await db.query("delete from public.carts where campaign_id in (select c.id from public.campaigns c join public.groups g on g.id=c.group_id where g.name=$1)", [marker]);
          await db.query("delete from public.campaigns where group_id in (select id from public.groups where name = $1)", [marker]);
          await db.query("delete from public.invites where group_id in (select id from public.groups where name = $1)", [marker]);
          await db.query("delete from public.idempotency_keys where actor_id = any($1::uuid[])", [users]);
          await db.query("delete from public.audit_events where actor_id = any($1::uuid[])", [users]);
          await db.query("delete from public.memberships where user_id = any($1::uuid[])", [users]);
          await db.query("delete from public.groups where name = $1", [marker]);
          await db.query("delete from public.profiles where id = any($1::uuid[])", [users]);
          await db.query("COMMIT");
        } catch (error) {
          await db.query("ROLLBACK");
          throw error;
        }
        for (const id of users) {
          const { error } = await admin.deleteUser(id);
          assert(!error, `Không dọn được tài khoản test ${id}.`);
        }
        console.log("Cleaned up temporary test accounts and group.");
      }
    } finally { await db.end(); }
  }
}

smoke().catch(error => {
  console.error("Registration smoke failed:", error.message);
  process.exitCode = 1;
});
